"""Publish only media and covers referenced by the two existing downloaded libraries."""
from pathlib import Path
import json,os,re,hashlib,shutil,subprocess
R=Path(__file__).resolve().parents[1];D=R/'dist';MEDIA=D/'media'
root=Path(os.environ.get('APPDATA',r'C:\Users\Administrator\AppData\Roaming'))
summary=[]
for app,id in [('MusicForYou','music'),('EchoPod','podcast')]:
 source=Path(os.environ.get('AIONE_'+id.upper()+'_ROOT',str(root/app)))
 if not (source/'library.json').exists():
  print('Source library not found; preserving the tracked catalog for '+id)
  continue
 entries=json.loads((source/'library.json').read_text('utf-8'));items=[]
 for e in entries:
  name=e.get('fileName','')
  if not name or Path(name).name!=name:continue
  f=source/'media'/name
  if not f.is_file():continue
  uid=hashlib.sha256((app+':'+str(e.get('id',name))).encode()).hexdigest()[:20]
  dest=MEDIA/id/'audio'/(uid+f.suffix.lower());dest.parent.mkdir(parents=True,exist_ok=True)
  if not dest.exists():
   try:os.link(f,dest)
   except OSError:shutil.copy2(f,dest)
  cover=''
  cn=e.get('coverName','')
  if cn and Path(cn).name==cn:
   cf=source/'covers'/cn
   if not cf.exists():cf=source/'media'/cn
   if cf.exists():
    target=MEDIA/id/'covers'/(uid+cf.suffix.lower());target.parent.mkdir(parents=True,exist_ok=True)
    if not target.exists():
     try:os.link(cf,target)
     except OSError:shutil.copy2(cf,target)
    cover='../../media/'+id+'/covers/'+target.name
  tags=[t.get('label','') if isinstance(t,dict) else str(t) for t in e.get('tags',[])]
  audiobook=any(x in ' '.join(tags)+e.get('title','') for x in ['有声','小说','听书','audiobook'])
  title=e.get('title','未命名音频')
  if title.startswith(('？','?a=')):title='未命名收藏音频'
  duration=e.get('duration',0)
  probe=shutil.which('ffprobe') or r'D:\AIPROJECT\douyin\vendor\bin\ffprobe.exe'
  if not duration and Path(probe).exists():
   try:duration=float(subprocess.check_output([probe,'-v','error','-show_entries','format=duration','-of','default=noprint_wrappers=1:nokey=1',str(f)],text=True,timeout=15).strip())
   except (subprocess.SubprocessError,ValueError):pass
  items.append({'id':uid,'title':title,'artist':e.get('artist') or e.get('channel') or '已收藏音频','duration':duration,'kind':'有声书' if audiobook else ('播客' if id=='podcast' else '音乐'),'tags':tags,'category':e.get('category',''),'url':'../../media/'+id+'/audio/'+dest.name,'cover':cover,'bytes':f.stat().st_size})
 data={'title':'音乐与有声书' if id=='music' else '播客精选','items':items,'count':len(items)}
 p=D/'apps'/id;p.mkdir(parents=True,exist_ok=True);(p/'library.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
 summary.append({'app':app,'count':len(items),'bytes':sum(t['bytes'] for t in items),'audiobooks':sum(t['kind']=='有声书' for t in items)})
print(json.dumps(summary,ensure_ascii=False))

for id,title,lead in [('music','musicForYou','已经收藏的音乐与有声书，打开就能听。'),('podcast','bokeForYou','已下载的播客精选，让好内容陪你慢慢走。')]:
 html=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · 在线聆听 · AIONE1</title><link rel="stylesheet" href="../../assets/apps.css"><link rel="stylesheet" href="../../assets/library.css"><script src="app.js" defer></script></head><body><main class="app library-app"><header><a href="../../">AIONE1 / 姚毛毛</a><a href="../../tools/{id}/">关于这个工具 ↗</a></header><section class="library-hero"><div><p class="hint">YOUR SOUND COLLECTION / 在线声音馆</p><h1>{title}<span> {('音乐与有声书' if id=='music' else '播客精选')}</span></h1><p class="lead">{lead}</p></div><div class="library-summary"><b id="total">—</b><span>份声音 · 等你发现</span></div></section><div class="library-tools"><div id="kinds" class="controls" role="group" aria-label="内容分类"></div><input type="search" id="search" placeholder="搜索标题、作者或标签…" aria-label="搜索曲库"></div><p id="status" class="status" role="status">正在载入已收藏曲库…</p><section id="catalog" class="album-grid" aria-label="曲库"></section><div class="library-empty" id="empty" hidden>还没有找到，换个关键词试试。</div><p class="hint library-note">曲库由站点预置。播放进度与收藏仅保存在你当前的浏览器中。</p><section class="player-bar" aria-label="播放器"><img id="cover" alt="" hidden><div class="playing-info"><b id="track">选择一份声音，开始聆听</b><small id="artist">从预置曲库中选择即可播放</small></div><div class="transport"><button id="prev" aria-label="上一首">←</button><button id="play" class="primary">播放</button><button id="next" aria-label="下一首">→</button></div><label class="rate-label">倍速<select id="rate" aria-label="播放倍速"><option value="0.75">0.75×</option><option value="1" selected>1×</option><option value="1.25">1.25×</option><option value="1.5">1.5×</option><option value="2">2×</option></select></label><audio controls preload="metadata"></audio></section></main></body></html>'''
 (D/'apps'/id/'index.html').write_text(html,encoding='utf-8')
 (D/'apps'/id/'app.js').write_text("""(()=>{const $=s=>document.querySelector(s),audio=$('audio');let items=[],current=-1,kind='全部',lastSave=0;const prefix='aione1.library.'+location.pathname;function load(k,fallback){try{return JSON.parse(localStorage.getItem(prefix+k))??fallback}catch{return fallback}}function store(k,v){try{localStorage.setItem(prefix+k,JSON.stringify(v))}catch{}}let saved=load('progress',{}),favorites=load('favorites',[]);const format=n=>{n=Math.max(0,Number(n)||0);const h=Math.floor(n/3600),m=Math.floor(n%3600/60);return h?h+' 小时 '+m+' 分':m+' 分钟'};function card(t,i){const a=document.createElement('article');a.className='album'+(i===current?' active':'');const button=document.createElement('button');button.className='album-open';button.setAttribute('aria-label','播放 '+t.title);const art=document.createElement('div');art.className='album-art';if(t.cover){const im=document.createElement('img');im.src=t.cover;im.alt='';im.loading='lazy';im.onerror=()=>im.remove();art.append(im)}const badge=document.createElement('span');badge.className='album-badge';badge.textContent=t.kind;const arrow=document.createElement('span');arrow.className='album-play';arrow.textContent='▶';art.append(badge,arrow);const body=document.createElement('div');body.className='album-body';const h=document.createElement('h2');h.textContent=t.title;const author=document.createElement('p');author.textContent=t.artist;const meta=document.createElement('small');meta.textContent=format(t.duration)+(saved[t.id]>10?' · 已听 '+format(saved[t.id]):'');body.append(h,author,meta);button.append(art,body);button.onclick=()=>select(i,true);const star=document.createElement('button');star.className='favorite';star.setAttribute('aria-label','收藏 '+t.title);star.setAttribute('aria-pressed',String(favorites.includes(t.id)));star.textContent=favorites.includes(t.id)?'★':'☆';star.onclick=()=>{favorites=favorites.includes(t.id)?favorites.filter(v=>v!==t.id):[...favorites,t.id];store('favorites',favorites);render()};a.append(button,star);return a}function render(){const q=$('#search').value.trim().toLowerCase(),root=$('#catalog');root.replaceChildren();items.forEach((t,i)=>{if(kind==='收藏'&&!favorites.includes(t.id)||!['全部','收藏'].includes(kind)&&t.kind!==kind)return;if(![t.title,t.artist,...t.tags].join(' ').toLowerCase().includes(q))return;root.append(card(t,i))});$('#empty').hidden=root.children.length>0;[...$('#kinds').children].forEach(b=>b.classList.toggle('primary',b.textContent===kind))}function select(i,play){if(!items[i])return;if(current>=0&&audio.currentTime>0){saved[items[current].id]=audio.currentTime;store('progress',saved)}current=i;const t=items[i];audio.src=t.url;$('#track').textContent=t.title;$('#artist').textContent=t.artist+' · '+t.kind;$('#cover').hidden=!t.cover;if(t.cover)$('#cover').src=t.cover;store('last',t.id);audio.onloadedmetadata=()=>{const pos=saved[t.id]||0;if(pos>5&&pos<(audio.duration||Infinity)-10)audio.currentTime=pos;audio.playbackRate=Number($('#rate').value)};if(play)audio.play().catch(()=>$('#status').textContent='请点击播放器中的播放按钮开始聆听');render();if('mediaSession'in navigator&&'MediaMetadata'in window){navigator.mediaSession.metadata=new MediaMetadata({title:t.title,artist:t.artist,album:t.kind,...(t.cover?{artwork:[{src:new URL(t.cover,location.href).href}]}:{})})}}$('#play').onclick=()=>{if(current<0&&items.length){select(0,true);return}if(audio.paused)audio.play().catch(()=>{});else audio.pause()};$('#prev').onclick=()=>items.length&&select((current-1+items.length)%items.length,true);$('#next').onclick=()=>items.length&&select((current+1)%items.length,true);audio.onplay=()=>{$('#play').textContent='暂停';$('#status').textContent='正在播放 · '+items[current].kind};audio.onpause=()=>$('#play').textContent='播放';audio.ontimeupdate=()=>{if(current>=0&&Date.now()-lastSave>5000){saved[items[current].id]=audio.currentTime;store('progress',saved);lastSave=Date.now()}};audio.onended=()=>{if(current>=0){saved[items[current].id]=0;store('progress',saved)}if(items.length)select((current+1)%items.length,true)};audio.onerror=()=>$('#status').textContent='该音频暂时无法载入，请稍后重试或选择其他内容。';$('#rate').onchange=e=>audio.playbackRate=Number(e.target.value);$('#search').oninput=render;fetch('library.json',{cache:'no-cache'}).then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{items=d.items;$('#total').textContent=items.length;for(const k of ['全部',...new Set(items.map(t=>t.kind)),'收藏']){const b=document.createElement('button');b.textContent=k;b.onclick=()=>{kind=k;render()};$('#kinds').append(b)}$('#status').textContent='曲库已就绪，选择一份声音即可播放。';render();const last=load('last','');const index=items.findIndex(t=>t.id===last);if(index>=0)select(index,false)}).catch(()=>$('#status').textContent='曲库正在同步，请稍后刷新。');window.addEventListener('beforeunload',()=>{if(current>=0){saved[items[current].id]=audio.currentTime;store('progress',saved)}})})();""",encoding='utf-8')
(D/'assets'/'library.css').write_text(""".library-app{max-width:1280px;padding-bottom:180px}.library-hero{display:flex;justify-content:space-between;align-items:center;padding:32px 0 25px}.library-hero h1{margin:5px 0 14px;font-size:36px;letter-spacing:-1px}.library-hero h1>span{font-size:15px;font-weight:400;color:#94a387;letter-spacing:1px;margin-left:15px}.library-summary{text-align:right;display:flex;flex-direction:column;gap:4px;color:#91a380;font-size:10px}.library-summary b{font:48px Georgia;color:#6b8756}.library-tools{display:flex;gap:25px;align-items:center;justify-content:space-between;padding:22px 0;border-top:1px solid #dde5d4;border-bottom:1px solid #dde5d4}.library-tools input{max-width:310px;margin:0!important;background:white!important}.library-tools button{padding:8px 17px;font-size:12px}.album-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:26px}.album{position:relative;background:white;border:1px solid #e0e8d9;border-radius:10px;overflow:hidden;transition:transform .2s}.album:hover{transform:translateY(-3px)}.album.active{border-color:#90aa72;box-shadow:0 6px 25px #5a783414}.album-open{border:0;padding:0;text-align:left;width:100%;display:block;background:transparent;color:inherit;border-radius:0}.album-art{height:170px;background:radial-gradient(ellipse at 30% 20%,#f0f3e3,#b6c8a1);position:relative;overflow:hidden}.album-art img{width:100%;height:100%;object-fit:cover}.album-art:after{content:'';position:absolute;inset:50% 0 0;background:linear-gradient(transparent,#13261366)}.album-badge{position:absolute;top:13px;left:13px;font-size:9px;background:#ffffffdb;padding:2px 9px;border-radius:20px;color:#61724f;z-index:1}.album-play{position:absolute;right:15px;bottom:15px;width:32px;height:32px;display:grid;place-items:center;border:1px solid #ffffff88;background:#ffffff44;border-radius:50%;font-size:10px;color:white;z-index:1}.album-body{padding:20px 20px 25px;min-height:148px}.album-body h2{font-size:14px;line-height:1.7;font-weight:500;margin:0 0 10px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;min-height:47px;padding-right:20px}.album-body p{font-size:11px;color:#96a28a;margin:0 0 10px}.album-body small{font-size:9px;color:#a0ac93}.favorite{position:absolute;bottom:21px;right:15px;padding:3px 7px;border:0;background:transparent;font-size:23px;color:#9eaf88}.favorite[aria-pressed=true]{color:#a18b4d}.player-bar{position:fixed;bottom:0;left:50%;transform:translateX(-50%);width:100%;max-width:1250px;border:1px solid #dce5d0;border-bottom:0;background:#fbfcf7f5;box-shadow:0 -8px 30px #3a4e2910;padding:20px 25px;display:grid;grid-template-columns:50px 1fr auto 85px;align-items:center;gap:20px;border-radius:12px 12px 0 0;backdrop-filter:blur(12px);z-index:10}.player-bar>img{width:50px;height:50px;object-fit:cover;border-radius:6px}.playing-info{display:flex;flex-direction:column;min-width:0;grid-column:2}.playing-info b{font-size:12px;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.playing-info small{font-size:10px;color:#9ca88f;margin-top:6px}.transport{display:flex;gap:8px}.transport button{padding:7px 12px;font-size:12px}.rate-label{font-size:9px}.rate-label select{font-size:11px;padding:5px!important;margin:0!important}.player-bar audio{grid-column:1/-1;margin:0;height:32px}.library-note{padding:25px 0}.library-empty{padding:70px 20px;text-align:center;color:#96a387}@media(max-width:850px){.album-grid{grid-template-columns:repeat(2,1fr)}.album-art{height:150px}.library-hero h1{font-size:30px}.library-hero h1>span{display:block;margin:10px 0 0;font-size:12px}.player-bar{padding:15px;gap:12px;grid-template-columns:38px 1fr auto 60px}.player-bar>img{width:38px;height:38px}.transport button{padding:6px 9px}}@media(max-width:550px){.library-app{padding-bottom:180px}.library-tools{display:block}.library-tools input{max-width:none;margin-top:15px!important}.album-grid{gap:14px}.album-art{height:115px}.album-body{padding:15px 12px 22px;min-height:149px}.album-body h2{font-size:12px;padding:0;min-height:61px;-webkit-line-clamp:3}.album-body p{font-size:9px;white-space:nowrap;text-overflow:ellipsis;overflow:hidden}.album-body small{font-size:8px}.favorite{bottom:12px;right:6px;font-size:20px}.library-summary b{font-size:37px}.library-summary span{font-size:8px}.player-bar{gap:10px;grid-template-columns:32px 1fr auto}.player-bar>img{width:32px;height:32px}.playing-info{grid-column:2}.playing-info b{font-size:10px}.playing-info small{font-size:8px}.rate-label{grid-column:3;grid-row:2;display:flex;gap:4px;align-items:center}.transport{grid-column:3}.player-bar audio{grid-column:1/3;height:35px}.transport button{font-size:10px;padding:5px 7px}.library-hero{padding-top:25px}.library-hero .hint{font-size:8px}.library-hero h1{font-size:27px}.library-hero .lead{font-size:11px}}""",encoding='utf-8')
